1	use serde::{Deserialize, Serialize};
2	use wasm_bindgen::prelude::*;
3	use yew::prelude::*;
4	
5	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
6	struct SceneMeta {
7	    title: String,
8	    environment: String,
9	    frames: u32,
10	}
11	
12	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
13	struct ObjectSpec {
14	    #[serde(rename = "type")]
15	    kind: String,
16	    name: String,
17	    label: String,
18	    position: [f32; 3],
19	}
20	
21	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
22	#[serde(untagged)]
23	enum Anchor {
24	    Object { object: String },
25	    World { world: [f32; 3] },
26	}
27	
28	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
29	#[serde(tag = "kind", rename_all = "snake_case")]
30	enum Callout {
31	    Tooltip {
32	        anchor: Anchor,
33	        #[serde(default)]
34	        offset: [f32; 3],
35	        #[serde(default)]
36	        title: Option<String>,
37	        text: String,
38	    },
39	    Link {
40	        anchor: Anchor,
41	        #[serde(default)]
42	        offset: [f32; 3],
43	        text: String,
44	        url: String,
45	    },
46	    SvgBillboard {
47	        anchor: Anchor,
48	        #[serde(default)]
49	        offset: [f32; 3],
50	        svg: String,
51	        #[serde(default = "default_billboard_width")]
52	        width: u32,
53	    },
54	    HtmlPanel {
55	        anchor: Anchor,
56	        #[serde(default)]
57	        offset: [f32; 3],
58	        #[serde(default)]
59	        title: Option<String>,
60	        html: String,
61	    },
62	}
63	
64	fn default_billboard_width() -> u32 {
65	    260
66	}
67	
68	impl Callout {
69	    fn anchor(&self) -> &Anchor {
70	        match self {
71	            Callout::Tooltip { anchor, .. }
72	            | Callout::Link { anchor, .. }
73	            | Callout::SvgBillboard { anchor, .. }
74	            | Callout::HtmlPanel { anchor, .. } => anchor,
75	        }
76	    }
77	    fn offset(&self) -> [f32; 3] {
78	        match self {
79	            Callout::Tooltip { offset, .. }
80	            | Callout::Link { offset, .. }
81	            | Callout::SvgBillboard { offset, .. }
82	            | Callout::HtmlPanel { offset, .. } => *offset,
83	        }
84	    }
85	    fn kind_str(&self) -> &'static str {
86	        match self {
87	            Callout::Tooltip { .. } => "tooltip",
88	            Callout::Link { .. } => "link",
89	            Callout::SvgBillboard { .. } => "svg_billboard",
90	            Callout::HtmlPanel { .. } => "html_panel",
91	        }
92	    }
93	}
94	
95	fn resolve_anchor(anchor: &Anchor, objects: &[ObjectSpec]) -> Option<[f32; 3]> {
96	    match anchor {
97	        Anchor::Object { object } => objects
98	            .iter()
99	            .find(|o| &o.name == object)
100	            .map(|o| o.position),
101	        Anchor::World { world } => Some(*world),
102	    }
103	}
104	
105	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
106	struct Scene {
107	    scene: SceneMeta,
108	    objects: Vec<ObjectSpec>,
109	    #[serde(default)]
110	    callouts: Vec<Callout>,
111	}
112	
113	#[wasm_bindgen]
114	extern "C" {
115	    #[wasm_bindgen(js_namespace = window, js_name = initThree)]
116	    fn init_three(canvas_id: &str, glb_url: &str);
117	    #[wasm_bindgen(js_namespace = window, js_name = focusObject)]
118	    fn focus_object(name: &str, x: f32, y: f32, z: f32);
119	    #[wasm_bindgen(js_namespace = window, js_name = initCallouts)]
120	    fn init_callouts(json: &str);
121	}
122	
123	#[function_component(App)]
124	fn app() -> Html {
125	    let scene = use_state(|| None::<Scene>);
126	    let error = use_state(|| None::<String>);
127	
128	    {
129	        let scene = scene.clone();
130	        let error = error.clone();
131	        use_effect_with((), move |_| {
132	            wasm_bindgen_futures::spawn_local(async move {
133	                match fetch_scene().await {
134	                    Ok(s) => {
135	                        scene.set(Some(s));
136	                    }
137	                    Err(e) => error.set(Some(e)),
138	                }
139	            });
140	            || ()
141	        });
142	    }
143	
144	    // Once the scene is in state, fire init_three + init_callouts on the next
145	    // render so the canvas and DOM callouts exist in the document.
146	    {
147	        let scene_dep = scene.clone();
148	        use_effect_with((*scene_dep).clone(), move |s| {
149	            if let Some(scene) = s {
150	                init_three("viz", "/minimal_scene.glb");
151	                let payload = build_callout_payload(scene);
152	                init_callouts(&payload);
153	            }
154	            || ()
155	        });
156	    }
157	
158	    if let Some(msg) = (*error).clone() {
159	        return html! { <div class="error">{ format!("scene.json error: {msg}") }</div> };
160	    }
161	
162	    let title = scene
163	        .as_ref()
164	        .map(|s| s.scene.title.clone())
165	        .unwrap_or_else(|| "Loading scene…".into());
166	    let objects = scene
167	        .as_ref()
168	        .map(|s| s.objects.clone())
169	        .unwrap_or_default();
170	    let callouts = scene
171	        .as_ref()
172	        .map(|s| s.callouts.clone())
173	        .unwrap_or_default();
