1	//! `cargo run --example ml-test-scene`
2	//!
3	//! Builds the Yew/WASM frontend with wasm-pack, then serves the static HTML,
4	//! CSS, JS glue, wasm bundle, scene spec, and the Blender-exported .glb on
5	//! 0.0.0.0:9521 so the page is reachable from other devices on the LAN.
6	
7	use std::{
8	    fs,
9	    path::{Path, PathBuf},
10	    process::Command,
11	};
12	use tiny_http::{Header, Method, Response, Server, StatusCode};
13	
14	const BIND: &str = "0.0.0.0:9521";
15	
16	fn main() {
17	    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
18	    let yew_app = manifest_dir.join("yew-app");
19	    let static_dir = yew_app.join("static");
20	    let pkg_dir = yew_app.join("pkg");
21	    let generated = manifest_dir.join("generated");
22	    let scenes = manifest_dir.join("scenes");
23	
24	    if !yew_app.is_dir() {
25	        eprintln!("error: yew-app/ not found at {}", yew_app.display());
26	        std::process::exit(1);
27	    }
28	
29	    build_wasm(&yew_app);
30	
31	    let scene_json = load_scene_json(&scenes.join("minimal.yaml")).unwrap_or_else(|e| {
32	        eprintln!("warn: could not load scenes/minimal.yaml — {e}");
33	        eprintln!("      run `cargo run -- init-scene scenes/minimal.yaml` first");
34	        "{}".into()
35	    });
36	
37	    let glb_path = generated.join("minimal_scene.glb");
38	    if !glb_path.is_file() {
39	        eprintln!("warn: {} not found — run", glb_path.display());
40	        eprintln!(
41	            "      cargo run -- gen-blender scenes/minimal.yaml --out generated/minimal_scene.py"
42	        );
43	        eprintln!("      blender -b --python generated/minimal_scene.py");
44	        eprintln!("      to generate it; the page will fall back to a placeholder cube.");
45	    }
46	
47	    let server = Server::http(BIND).expect("bind 0.0.0.0:9521");
48	    println!();
49	    println!("ml-viz Yew/WASM demo");
50	    println!("  http://localhost:9521    (this machine)");
51	    println!("  http://{}                (LAN)", lan_url(BIND));
52	    println!();
53	    println!("Press Ctrl-C to stop.");
54	
55	    for req in server.incoming_requests() {
56	        if !matches!(req.method(), Method::Get | Method::Head) {
57	            let _ = req.respond(Response::empty(StatusCode(405)));
58	            continue;
59	        }
60	        let raw = req.url().to_string();
61	        let path = raw.split('?').next().unwrap_or("/");
62	        let logical = if path == "/" { "/index.html" } else { path };
63	        log_req(req.method(), logical);
64	
65	        if logical == "/scene.json" {
66	            let _ = req.respond(
67	                Response::from_string(scene_json.clone())
68	                    .with_header(header("Content-Type", "application/json"))
69	                    .with_header(header("Cache-Control", "no-store")),
70	            );
71	            continue;
72	        }
73	
74	        match resolve(logical, &static_dir, &pkg_dir, &generated, &manifest_dir) {
75	            Some(file) => match fs::read(&file) {
76	                Ok(bytes) => {
77	                    let mime = mime_for(&file);
78	                    let _ = req.respond(
79	                        Response::from_data(bytes)
80	                            .with_header(header("Content-Type", mime))
81	                            .with_header(header("Cache-Control", "no-store")),
82	                    );
83	                }
84	                Err(e) => {
85	                    eprintln!("  500 {}: {e}", file.display());
86	                    let _ = req.respond(
87	                        Response::from_string(format!("read error: {e}")).with_status_code(500),
88	                    );
89	                }
90	            },
91	            None => {
92	                let _ = req.respond(
93	                    Response::from_string(format!("not found: {logical}")).with_status_code(404),
94	                );
95	            }
96	        }
97	    }
98	}
99	
100	fn build_wasm(yew_app: &Path) {
101	    println!("→ wasm-pack build (yew-app)");
102	    let status = Command::new("wasm-pack")
103	        .args([
104	            "build",
105	            "--target",
106	            "web",
107	            "--out-dir",
108	            "pkg",
109	            "--out-name",
110	            "viz",
111	            "--dev",
112	        ])
113	        .current_dir(yew_app)
114	        .status();
115	    match status {
116	        Ok(s) if s.success() => {}
117	        Ok(s) => {
118	            eprintln!("wasm-pack exited with status {s}");
119	            std::process::exit(1);
120	        }
121	        Err(e) => {
122	            eprintln!("failed to invoke wasm-pack: {e}");
123	            eprintln!("install with: cargo install wasm-pack");
124	            std::process::exit(1);
125	        }
126	    }
127	}
128	
129	fn load_scene_json(yaml_path: &Path) -> Result<String, String> {
130	    let text = fs::read_to_string(yaml_path).map_err(|e| e.to_string())?;
131	    let value: serde_yaml::Value = serde_yaml::from_str(&text).map_err(|e| e.to_string())?;
132	    serde_json::to_string_pretty(&value).map_err(|e| e.to_string())
133	}
134	
135	fn resolve(
136	    logical: &str,
137	    static_dir: &Path,
138	    pkg_dir: &Path,
139	    generated: &Path,
140	    manifest_dir: &Path,
141	) -> Option<PathBuf> {
142	    let trimmed = logical.trim_start_matches('/');
143	    if trimmed.contains("..") {
144	        return None;
145	    }
146	    if let Some(rest) = trimmed.strip_prefix("pkg/") {
147	        return file_in(pkg_dir, rest);
148	    }
149	    if let Some(rest) = trimmed.strip_prefix("assets/") {
150	        return file_in(&manifest_dir.join("assets"), rest);
151	    }
152	    if let Some(p) = file_in(static_dir, trimmed) {
153	        return Some(p);
154	    }
155	    if let Some(p) = file_in(generated, trimmed) {
156	        return Some(p);
157	    }
158	    None
159	}
160	
161	fn file_in(base: &Path, rest: &str) -> Option<PathBuf> {
162	    let candidate = base.join(rest);
163	    if candidate.is_file() {
164	        Some(candidate)
165	    } else {
166	        None
167	    }
168	}
169	
170	fn mime_for(p: &Path) -> &'static str {
171	    match p.extension().and_then(|s| s.to_str()) {
172	        Some("html") => "text/html; charset=utf-8",
173	        Some("css") => "text/css; charset=utf-8",
174	        Some("js") | Some("mjs") => "application/javascript; charset=utf-8",
175	        Some("wasm") => "application/wasm",
176	        Some("json") => "application/json",
177	        Some("glb") => "model/gltf-binary",
178	        Some("gltf") => "model/gltf+json",
179	        Some("svg") => "image/svg+xml",
180	        Some("png") => "image/png",
181	        Some("ico") => "image/x-icon",
182	        _ => "application/octet-stream",
183	    }
184	}
185	
186	fn header(name: &str, value: &str) -> Header {
187	    Header::from_bytes(name.as_bytes(), value.as_bytes()).expect("static header")
188	}
189	
190	fn log_req(method: &Method, path: &str) {
191	    println!("  {method:>4} {path}");
192	}
193	
194	fn lan_url(bind: &str) -> String {
195	    // Best-effort LAN hint without bringing in extra deps: ask the OS for a
196	    // routable address by connecting a UDP socket to a public IP.
197	    use std::net::UdpSocket;
198	    let port = bind.rsplit(':').next().unwrap_or("9521");
199	    let ip = UdpSocket::bind("0.0.0.0:0")
200	        .and_then(|s| {
201	            s.connect("1.1.1.1:80")?;
202	            s.local_addr()
203	        })
204	        .map(|a| a.ip().to_string())
205	        .unwrap_or_else(|_| "0.0.0.0".into());
206	    format!("{ip}:{port}")
207	}
