use serde::{Deserialize, Serialize};
use wasm_bindgen::prelude::*;
use yew::prelude::*;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
struct SceneMeta {
    title: String,
    environment: String,
    frames: u32,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
struct ObjectSpec {
    #[serde(rename = "type")]
    kind: String,
    name: String,
    label: String,
    position: [f32; 3],
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(untagged)]
enum Anchor {
    Object { object: String },
    World { world: [f32; 3] },
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(tag = "kind", rename_all = "snake_case")]
enum Callout {
    Tooltip {
        anchor: Anchor,
        #[serde(default)]
        offset: [f32; 3],
        #[serde(default)]
        title: Option<String>,
        text: String,
    },
    Link {
        anchor: Anchor,
        #[serde(default)]
        offset: [f32; 3],
        text: String,
        url: String,
    },
    SvgBillboard {
        anchor: Anchor,
        #[serde(default)]
        offset: [f32; 3],
        svg: String,
        #[serde(default = "default_billboard_width")]
        width: u32,
    },
    HtmlPanel {
        anchor: Anchor,
        #[serde(default)]
        offset: [f32; 3],
        #[serde(default)]
        title: Option<String>,
        html: String,
    },
}

fn default_billboard_width() -> u32 {
    260
}

impl Callout {
    fn anchor(&self) -> &Anchor {
        match self {
            Callout::Tooltip { anchor, .. }
            | Callout::Link { anchor, .. }
            | Callout::SvgBillboard { anchor, .. }
            | Callout::HtmlPanel { anchor, .. } => anchor,
        }
    }
    fn offset(&self) -> [f32; 3] {
        match self {
            Callout::Tooltip { offset, .. }
            | Callout::Link { offset, .. }
            | Callout::SvgBillboard { offset, .. }
            | Callout::HtmlPanel { offset, .. } => *offset,
        }
    }
    fn kind_str(&self) -> &'static str {
        match self {
            Callout::Tooltip { .. } => "tooltip",
            Callout::Link { .. } => "link",
            Callout::SvgBillboard { .. } => "svg_billboard",
            Callout::HtmlPanel { .. } => "html_panel",
        }
    }
}

fn resolve_anchor(anchor: &Anchor, objects: &[ObjectSpec]) -> Option<[f32; 3]> {
    match anchor {
        Anchor::Object { object } => objects
            .iter()
            .find(|o| &o.name == object)
            .map(|o| o.position),
        Anchor::World { world } => Some(*world),
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
